(function(E){ const x = E["sales-m4"] = E["sales-m4"] || {units:{}}; x.units["sales-cp-4"] = {"exit":{"id":"c-sales-cp-4-x","course":"sales","unit":"sales-cp-4","type":"exit","items":[{"from":"sales-4-1","kind":"blank","prompt":"The buyer asked ___ we could replace the broken jars.","options":["that","if","did"],"correct":1},{"from":"sales-4-1","kind":"mcq","prompt":"Which sorry is best?","options":["We apologise for any inconvenience.","I'm sorry about the 40 broken jars.","Sorry, but it's not our fault."],"correct":1},{"from":"sales-4-2","kind":"blank","prompt":"We ___ the problem yesterday, and we called you this morning.","options":["have found","found","have been finding"],"correct":1},{"from":"sales-4-2","kind":"mcq","prompt":"What should end a bad news message?","options":["Your next update","A new product","A joke"],"correct":0},{"from":"sales-4-3","kind":"blank","prompt":"Late deliveries have fallen ___ 6 to 1 this year.","options":["of","from","since"],"correct":1},{"from":"sales-4-3","kind":"mcq","prompt":"Which number belongs in an account review?","options":["The number of emails you sent","The bad result, and what you changed","Your own sales target"],"correct":1},{"from":"sales-3-3","kind":"mcq","prompt":"Why must documents match each other?","options":["A mismatch can delay payment or goods.","They look nicer and more professional.","Customs officers like long files to read."],"correct":0},{"from":"sales-2-1","kind":"blank","prompt":"What ___ your customers ask for most?","options":["do","does","are"],"correct":0}]},"writing":{"id":"c-sales-cp-4-w","course":"sales","unit":"sales-cp-4","type":"writing","difficulty":"medium","modelBy":"FEschool","portfolio":null,"title":{"en":"Your customer care plan","tr":"Müşteri bakım planın","fa":"برنامه‌ی نگهداری مشتری تو"},"prompt":{"en":"Project. Plan the next six months for your best customer, or a chain of 12 food shops with this record: stockouts down from 9 to 2 a year; one late order; two new shops in spring. Write (90-120 words): the customer's goal, what has gone well and badly, the worst thing that could go wrong and how you will tell them early, the date of your next review, and one offer that fits a need.","tr":"Proje. En iyi müşterin için önümüzdeki altı ayı planla ya da şu kayda sahip 12 mağazalı bir gıda zinciri için: stok tükenmesi yılda 9'dan 2'ye düştü; bir sipariş gecikti; ilkbaharda iki yeni mağaza. Yaz (90-120 kelime): müşterinin hedefi, neyin iyi ve kötü gittiği, olabilecek en kötü şey ve bunu erkenden nasıl bildireceğin, bir sonraki değerlendirme tarihi ve bir ihtiyaca uyan bir teklif.","fa":"پروژه. شش ماه آینده را برای بهترین مشتری‌ات، یا برای یک زنجیره‌ی ۱۲ فروشگاهی مواد غذایی با این سابقه، برنامه‌ریزی کن: کمبود موجودی از ۹ به ۲ بار در سال رسیده؛ یک سفارش دیر رسیده؛ دو فروشگاه تازه در بهار. بنویس (۹۰ تا ۱۲۰ کلمه): هدف مشتری، چه چیزی خوب و بد پیش رفته، بدترین اتفاق ممکن و اینکه چطور زود خبر می‌دهی، تاریخ مرور بعدی و یک پیشنهاد متناسب با یک نیاز."},"model":"Goal: no empty shelves in 12 shops.\n\nSo far: stockouts have fallen from 9 to 2 a year. One order came 8 days late, so we have changed the ship.\n\nBiggest risk: a port delay in winter. If it happens, I will call the buyer the same day, with a new date and a choice of air freight for part of the order.\n\nNext review: 15 June. I will send the numbers a week before and ask what has changed.\n\nOffer: two new shops open in spring, so I will suggest a first delivery plan for them in March.","frame":"Goal: ___.\n\nSo far: ___ have fallen from ___ to ___. ___, so we have ___.\n\nBiggest risk: ___. If it happens, I will ___.\n\nNext review: ___. I will ___.\n\nOffer: ___, so I will suggest ___.","words":[{"word":"have fallen"},{"word":"If it happens"},{"word":"Next review"}],"minWords":80,"minSentences":6,"rubric":["Task done: goal, record, risk, next review, one offer that fits","Organised: short headed parts","Language: present perfect up to now; from ... to; if + present","Tone: honest about the bad result; the offer serves a real need"],"rubricI18n":{"tr":["Görev: hedef, geçmiş, risk, sonraki değerlendirme, uygun bir teklif","Düzen: başlıklı kısa bölümler","Dil: şimdiye kadarki için present perfect; from ... to; if + geniş zaman","Üslup: kötü sonuç konusunda dürüst; teklif gerçek bir ihtiyaca yönelik"],"fa":["کامل بودن کار: هدف، سابقه، ریسک، مرور بعدی، یک پیشنهاد مناسب","نظم: بخش‌های کوتاه با عنوان","زبان: حال کامل برای کارهای تا الان؛ from ... to؛ if + زمان حال","لحن: صادق درباره‌ی نتیجه‌ی بد؛ پیشنهاد برای نیاز واقعی است"]}},"speaking":{"id":"sales-cp-4","course":"sales","unit":"sales-cp-4","topic":{"en":"Presenting your care plan","tr":"Bakım planını sunmak","fa":"ارائه‌ی برنامه‌ی نگهداری مشتری"},"warmup":{"en":"Which customer would hurt most to lose? Why?","tr":"Hangi müşteriyi kaybetmek en çok acıtır? Neden?","fa":"از دست دادن کدام مشتری بیشتر از همه گران تمام می‌شود؟ چرا؟"},"questions":[{"en":"Present your plan to the customer: their goal, the results and the bad number.","tr":"Planını müşteriye sun: hedefi, sonuçlar ve kötü rakam.","fa":"برنامه‌ات را به مشتری ارائه بده: هدفش، نتیجه‌ها و عدد بد."},{"en":"The customer says: \"Our last order was late, and nobody called us.\" Summarise, say sorry, say what has changed.","tr":"Müşteri diyor ki: \"Our last order was late, and nobody called us.\" Özetle, özür dile, neyin değiştiğini söyle.","fa":"مشتری می‌گوید: «Our last order was late, and nobody called us.» خلاصه کن، عذرخواهی کن و بگو چه چیزی عوض شده است."},{"en":"Ask what has changed on their side, and agree your next review date.","tr":"Onların tarafında neyin değiştiğini sor ve bir sonraki değerlendirme tarihinde anlaş.","fa":"بپرس در شرکت آن‌ها چه چیزی عوض شده و روی تاریخ مرور بعدی توافق کن."}],"followups":[{"en":"Put your next review date in your calendar now.","tr":"Bir sonraki değerlendirme tarihini şimdi takvimine yaz.","fa":"تاریخ مرور بعدی را همین حالا در تقویمت بگذار."}],"expressions":[{"phrase":"Your goal was ...","meaning":{"en":"Starts from their goal.","tr":"Onların hedefinden başlar.","fa":"از هدف آن‌ها شروع می‌کند."}},{"phrase":"From now on, we will ...","meaning":{"en":"Says what has changed.","tr":"Neyin değiştiğini söyler.","fa":"می‌گوید چه چیزی تغییر کرده است."}},{"phrase":"Shall we meet again on ...?","meaning":{"en":"Fixes the next review.","tr":"Sonraki değerlendirmeyi belirler.","fa":"مرور بعدی را مشخص می‌کند."}}],"model":"Your goal was no empty shelves. Stockouts have fallen from nine to two a year. Let me make sure I have this right: one order came late, and nobody called you. I'm sorry about that. From now on, we will call you the day we know. What has changed on your side? Two new shops? Good. Shall we meet again on fifteen June?","selfCheck":[{"en":"I started with their goal.","tr":"Onların hedefiyle başladım.","fa":"با هدف آن‌ها شروع کردم."},{"en":"I said the bad number myself.","tr":"Kötü rakamı kendim söyledim.","fa":"عدد بد را خودم گفتم."},{"en":"I said sorry for the exact thing.","tr":"Tam olarak o şey için özür diledim.","fa":"برای همان موضوع مشخص عذرخواهی کردم."},{"en":"I agreed a date.","tr":"Bir tarihte anlaştım.","fa":"روی یک تاریخ توافق کردم."}]}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
